func (c *current) onJoinedTable1(first, rest any) (any, error) {
	out := first.(ast.SQLTableExpr)
	for _, join := range rest.([]any) {
		switch join := join.(type) {
		case *ast.SQLCrossJoin:
			join.Left = out
			join.Loc.First = out.Pos()
		case *ast.SQLJoin:
			join.Left = out
			join.Loc.First = out.Pos()
		default:
			panic(join)
		}
		out = join.(ast.SQLTableExpr)
	}
	return out, nil

}

